package com.sahyadri.sahyadripooltrip.controller;
import com.sahyadri.sahyadripooltrip.entity.NatureDestination; import com.sahyadri.sahyadripooltrip.service.NatureDestinationService; import org.springframework.web.bind.annotation.*; import org.springframework.http.ResponseEntity; import java.util.*;
@RestController @RequestMapping("/api/destinations") @CrossOrigin(origins="*") public class NatureDestinationController{private final NatureDestinationService s;public NatureDestinationController(NatureDestinationService s){this.s=s;}@GetMapping public List<NatureDestination> all(){return s.all();}@GetMapping("/{locationId}") public ResponseEntity<?> byId(@PathVariable String locationId){return s.byId(locationId).<ResponseEntity<?>>map(ResponseEntity::ok).orElseGet(()->ResponseEntity.notFound().build());}@GetMapping("/count") public long count(){return s.count();}@GetMapping("/section/{section}") public List<NatureDestination> section(@PathVariable String section){return s.section(section);}@GetMapping("/state/{state}") public List<NatureDestination> state(@PathVariable String state){return s.state(state);}@GetMapping("/category/{category}") public List<NatureDestination> category(@PathVariable String category){return s.category(category);}@GetMapping("/section/{section}/state/{state}") public List<NatureDestination> sectionState(@PathVariable String section,@PathVariable String state){return s.sectionState(section,state);}}
